const request = $('Validate Webhook Secret').first().json.body;
const ollama = $input.first().json;
const parsed = typeof ollama.response === 'string' ? JSON.parse(ollama.response) : ollama.response;
const targetId = Number(request.targetId);
const parsedScore = Number(parsed.aiScore);
const candidateScore = Number.isFinite(parsedScore) ? (parsedScore >= 0 && parsedScore <= 1 ? parsedScore * 100 : parsedScore) : Number(request.fallbackScore);
const score = Math.round(Math.max(0, Math.min(100, candidateScore)));
return [{ json: {
  targetId,
  aiScore: score,
  fallbackScore: Number(request.fallbackScore),
  label: parsed.label || (score >= 80 ? 'Strong match' : score >= 60 ? 'Good match' : 'Possible match'),
  explanation: parsed.explanation || 'Ollama evaluated the supplied applicant and shift details.',
  strengths: Array.isArray(parsed.strengths) ? parsed.strengths : [],
  risks: Array.isArray(parsed.risks) ? parsed.risks : [],
  recommendedAction: parsed.recommendedAction || 'Review the application before deciding.',
  source: 'N8N_OLLAMA'
} }];
